from qiskit import QuantumCircuit
import math


def solve(n: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    # prepare |W_n> = 1/sqrt(n) sum_i |0...010...0>
    for i in range(n):
        theta = 2.0 * math.asin(1.0 / math.sqrt(n - i))
        if i == 0:
            qc.ry(theta, i)
        else:
            controls = list(range(i))
            for c in controls:
                qc.x(c)
            # multi-controlled Ry with controls = 1  <=>  zero control after X
            qc.mcry(theta, controls, i)
            for c in controls:
                qc.x(c)
    return qc
